function dir$dmloainganhnghe(p){
  this.constructor(p);
}
dir$dmloainganhnghe.prototype = new DirEvent();
dir$dmloainganhnghe.prototype.afterInit = function(){
  var p = this._dir;
}
dir$dmloainganhnghe.prototype.afterInit = function(renderType){
	var p = this._dir;
	dir$dmloainganhngheDisabledMasterField(p);
}

function dir$dmloainganhngheDisabledMasterField(p){
var maLoai = p.valForm('ma_loai');
	if(maLoai) {
		p.setDisabled('ma_loai', true);
	} else {
		p.setDisabled('ma_loai', false);
	}
}






